          "source_text": "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>Launch Validator</title>\n  <style>\n    body { font: 16px/1.45 system-ui, sans-serif; max-width: 760px; margin: 3rem auto; color: #1f2937; }\n    textarea { width: 100%; box-sizing: border-box; margin: .35rem 0 1rem; }\n    button { padding: .55rem .9rem; }\n    pre { background: #f3f4f6; padding: 1rem; min-height: 6rem; }\n  </style>\n</head>\n<body>\n  <h1>Launch Validator</h1>\n  <p>Enter one Android source item per line, then validate the launch gate.</p>\n  <label>Checklist items<br><textarea id=\"checklist\" rows=\"5\" cols=\"48\"></textarea></label><br>\n  <label>Playlist tracks<br><textarea id=\"tracks\" rows=\"5\" cols=\"48\"></textarea></label><br>\n  <button id=\"validate\">Validate</button>\n  <pre id=\"result\">Waiting for input.</pre>\n  <script>\n    function evaluateLaunchGate(checklist, playlistTracks) {\n      // TODO: replace these length-only checks with exact membership checks\n      // using the values visible on the two Android devices.\n      const checklistReady = Array.isArray(checklist) && checklist.length === 3;\n      const audioReady = Array.isArray(playlistTracks) && playlistTracks.length === 3;\n      return { checklistReady, audioReady, launch_passed: false };\n    }\n    globalThis.evaluateLaunchGate = evaluateLaunchGate;\n\n    const lines = id => document.querySelector(id).value.split(/\\r?\\n/).map(value => value.trim()).filter(Boolean);\n    document.querySelector('#validate').addEventListener('click', () => {\n      const checklist = lines('#checklist');\n      const tracks = lines('#tracks');\n      document.querySelector('#result').textContent = JSON.stringify({\n        ...evaluateLaunchGate(checklist, tracks),\n        checklist_items: checklist.length,\n        audio_tracks: tracks.length\n      }, null, 2);\n    });\n  </script>\n</body>\n</html>\n"
        }
